  ?point a brick:Zone
  ?point brick:hasLabel "DataCenter_mid_ZN_6"
  OPTIONAL {
    ?point ?rel ?relObj
  }
  OPTIONAL {
    ?point ref:hasTimeseriesId ?series
  }
}

SELECT ?point ?pc ?series WHERE {
  ?point ref:hasTimeseriesId ?series
  ?point a ?pc
  OPTIONAL { ?point brick:hasLabel ?lbl }
  FILTER (CONTAINS(str(?point), "ZN_6") || ?lbl = "DataCenter_mid_ZN_6")
}

SELECT ?point ?series WHERE {
  ?point ref:hasTimeseriesId ?series
  OPTIONAL { ?point brick:hasLabel ?lbl }
  FILTER (CONTAINS(str(?point), "ZN_6") || ?lbl = "DataCenter_mid_ZN_6")
}

